$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_f14c4e03d1054e002d679a266e3df63f'] = 'Opis oferty (bez znaczników HTML). Gdy jest pusty, używane jest podsumowanie.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_84ad795d7dabf7846310b7b19db3c163'] = 'Marka produktu.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_c4259facce39fa2243da017ce96d5c21'] = 'Twój kod produktu w ofercie. Kombinacje używają własnego (albo kodu produktu z dopiskiem „-<id kombinacji>”).';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_5a2024819c269492a07bb27eb22bef83'] = 'Kod kreskowy - służy też do wyszukania produktu w katalogu InPost. Kombinacje używają tylko własnego EAN.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_b7770c583f0d4fc1758d865ae2c8cd3e'] = 'Kod producenta - razem z marką identyfikuje produkt bez EAN. Kombinacje używają własnego MPN, jeśli jest ustawiony.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_e28c753b65918d059d6dd5e3191af161'] = 'Model produktu. Gdy pole jest puste, używana jest nazwa produktu.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_1a80211857b6d308b4cda14c599c60c3'] = 'Grupuje warianty jednego produktu. Oferty kombinacji zawsze używają nazwy produktu.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_b92503b2f8671208937e73c917360ef9'] = 'Przeliczane z jednostki wagi sklepu (%s) na gramy. Kombinacje doliczają swój wpływ na wagę.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_c030d96b8b5a362a29de366bf23337aa'] = 'Z jakich danych PrestaShop wypełniane są pola produktu nowych ofert. Istniejące oferty się nie zmieniają. Atrybuty kategorii InPost (np. „Kod producenta”) mapuje się osobno w Mapowaniu kategorii - tam też można wybrać pola produktu, np. MPN.';
