$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_82c43b7ba6d3c745703810a312afb8a1'] = 'Liczba dni do wysyłki, używana gdy ani oferta, ani mapowanie pola "Czas wysyłki (dni)" nie podaje wartości. Zostaw puste, aby jej nie wysyłać.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_723c8ce6450c233a3e54cb0ac624238d'] = 'Czas wysyłki (dni)';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_89d4d72d41a29c55b66af9e21d7965a5'] = 'Cecha produktu z liczbą dni do wysyłki, np. "3" lub "2-3 dni" (używana jest większa liczba). Dotyczy każdej oferty bez własnej wartości - także istniejących; gdy cecha jest pusta, używany jest domyślny czas wysyłki z sekcji Domyślne wartości ofert.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_d601d86e3ad3ac9565c2f0f6cf943e4c'] = 'Ceny w InPost';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_5d7ccd508f2ca5259a631d1a3eed0281'] = '-- brak: cena sklepu --';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_3f7196aa0866bdf59ba8f80ea20498e1'] = 'Ceny wysyłane do InPost. Ceny w Twoim sklepie się nie zmieniają. Oferta z ceną ręczną (ustawioną na ofercie albo przez „Ustaw cenę” na liście ofert) ją zachowuje - te ustawienia jej nie dotyczą.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_5e83cd6072eda8cd59f7f59a1da73ce1'] = 'Cena bazowa: cena dla wybranej poniżej grupy klientów albo cena sklepu, gdy grupa nie jest wybrana.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_4b8c7464358e48929141b3a43ea0bd07'] = 'Zmiana ceny: cena bazowa plus lub minus procent.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_17aad92cbb163138e0a42b4677317c4c'] = 'Zaokrąglenie wyniku.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_b99d7545d24e5e98a52bdfb286aa4246'] = 'Przykład: cena w sklepie 100,00, +5 %, zaokrąglenie do ,99 - cena w InPost 105,99.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_e158c416ab98063e6dc6a8a8aec5ab61'] = 'Po zmianie wszystkie oferty są przeliczane, a te, którym zmieniła się cena, wysyła do InPost cron synchronizacji ofert.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_727857f52518bce98f37732ce3a0b9a9'] = 'Grupa klientów cen w InPost';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_0c0fb9e48262be5bdaca72e72c6a3b7d'] = 'Oferty dostają cenę, jaką zapłaciłby klient tej grupy: jej ceny specyficzne, reguły cenowe katalogu i rabat grupy. Utwórz grupę (np. „InPost”) bez klientów i ustaw dla niej ceny InPost w Katalogu. Produkty bez takiej ceny dostają zwykłą cenę.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_6b258a5aa9b8cddae0cfe0b9a8157e6f'] = 'Zmiana ceny (%)';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_1205cc04b544d9d25522129e83bd99f4'] = 'Np. 5 = o 5%% drożej niż w sklepie, -5 = o 5%% taniej, 0 = tak samo. Od %s do %s.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_f81873c32fc169ee4afa8ea831f6aba4'] = 'Zaokrąglenie';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_c4904f9b66fd384d812f0756bc060d4a'] = 'Stosowane po zmianie ceny. „Brak” zostawia cenę dokładną (co do grosza).';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_6adf97f83acf6453d4a6a4b1070f3754'] = 'Brak';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_184189c369ae85e3fc31c4669f32e518'] = 'W górę do ,99 (104,20 -> 104,99)';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_e3911a117e18bafc12b75403bb07e3f3'] = 'Do pełnych złotych (104,49 -> 104,00)';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_4c3bdb471dfbc7fc4187a4d6f572334a'] = 'Zmiana ceny: podaj liczbę od %s do %s, np. 5 lub -3,5. Zostawiono poprzednią wartość.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_3e6408ff864c2390756dbd80bd363bd9'] = 'Ceny w InPost przeliczy cron synchronizacji ofert w ciągu kilku minut.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_0c609833cef13f23c9c0ff35c9f06ac2'] = 'Przeliczono ceny w InPost: sprawdzono ofert: %d, zmieniono: %d. Zmienione oferty wyśle do InPost cron synchronizacji ofert.';
$_MODULE['<{inpostvonhalsky}prestashop>inpostvonhalsky_8f81428527df83f4cd915d708384423b'] = 'Pozostałe oferty przeliczy cron synchronizacji ofert w ciągu kilku minut.';
